                        </Button>
                      </div>
                    </div>
                  )}
                </Card>
              ))
            )}
          </TabsContent>

          <TabsContent value="madefor" className="space-y-3">
            <Card className="p-6">
              <div className="flex gap-2 mb-4">
                <Input
                  placeholder="New entity"
