}: ExpenseListItemProps) {
  const accentColor = categoryColors[category] || "bg-primary";

  return (
    <Card
      className={`p-4 hover-elevate active-elevate-2 cursor-pointer transition-all border-l-4 ${accentColor} border-l-opacity-100`}
