import { useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

const editUserSchema = z.object({
  username: z.string().min(1, "Username is required"),
  fullName: z.string().min(1, "Full name is required"),
  firstName: z.string().min(1, "First name is required"),
  shortName: z.string().optional(),
  mobileNumber: z.string().optional(),
  role: z.enum(["admin", "standard"]),
});

type EditUserFormData = z.infer<typeof editUserSchema>;

interface User {
  id: string;
  username: string;
  fullName: string;
  firstName: string;
  role: string;
  mobileNumber?: string;
  shortName?: string;
}

interface EditUserDialogProps {
  user: User;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function EditUserDialog({
  user,
  open,
  onOpenChange,
}: EditUserDialogProps) {
  const { toast } = useToast();

  const form = useForm<EditUserFormData>({
    resolver: zodResolver(editUserSchema),
    defaultValues: {
      username: user.username,
      fullName: user.fullName,
      firstName: user.firstName,
      shortName: user.shortName || "",
      mobileNumber: user.mobileNumber || "",
      role: user.role as "admin" | "standard",
    },
  });

  const updateUserMutation = useMutation({
    mutationFn: async (data: EditUserFormData) => {
      const response = await apiRequest("PATCH", `/api/users/${user.id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/users"] });
      toast({
        title: "User updated",
        description: "User details have been saved successfully",
      });
      onOpenChange(false);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update user",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: EditUserFormData) => {
    updateUserMutation.mutate(data);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent data-testid="dialog-edit-user">
        <DialogHeader>
          <DialogTitle>Edit User</DialogTitle>
          <DialogDescription>
            Update user details and permissions
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="username"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Username</FormLabel>
                  <FormControl>
                    <Input data-testid="input-username" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="fullName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Full Name</FormLabel>
                  <FormControl>
                    <Input data-testid="input-fullname" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="firstName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>First Name</FormLabel>
                  <FormControl>
                    <Input data-testid="input-firstname" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="shortName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Short Name (Optional)</FormLabel>
                  <FormControl>
                    <Input data-testid="input-shortname" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="mobileNumber"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Mobile Number (Optional)</FormLabel>
                  <FormControl>
                    <Input data-testid="input-mobile" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="role"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Role</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger data-testid="select-role">
                        <SelectValue />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="standard">Standard</SelectItem>
                      <SelectItem value="admin">Admin</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />
            <div className="flex gap-2 justify-end">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                data-testid="button-cancel"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={updateUserMutation.isPending}
                data-testid="button-submit"
              >
                {updateUserMutation.isPending ? "Saving..." : "Save Changes"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/admin/ColorEditor..content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Save } from "lucide-react";

interface AppColor {
  id: string;
  colorKey: string;
  colorValue: string;
  description?: string;
}

export function ColorEditor() {
  const { toast } = useToast();
  const [editedColors, setEditedColors] = useState<Record<string, string>>({});

  const { data: colors = [], isLoading } = useQuery<AppColor[]>({
    queryKey: ["/api/admin/colors"],
  });

  const updateColorMutation = useMutation({
    mutationFn: async ({ id, colorValue }: { id: string; colorValue: string }) => {
      await apiRequest("PATCH", `/api/admin/colors/${id}`, { colorValue });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/colors"] });
      toast({
        title: "Colors updated",
        description: "Color settings have been saved successfully",
      });
      setEditedColors({});
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update colors",
        variant: "destructive",
      });
    },
  });

  const handleColorChange = (id: string, value: string) => {
    setEditedColors((prev) => ({
      ...prev,
      [id]: value,
    }));
  };

  const handleSave = () => {
    Object.entries(editedColors).forEach(([id, colorValue]) => {
      updateColorMutation.mutate({ id, colorValue });
    });
  };

  const hasChanges = Object.keys(editedColors).length > 0;

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Color Customization</CardTitle>
            <CardDescription>
              Customize colors used throughout the application
            </CardDescription>
          </div>
          {hasChanges && (
            <Button
              onClick={handleSave}
              disabled={updateColorMutation.isPending}
              data-testid="button-save-colors"
            >
              <Save className="h-4 w-4 mr-2" />
              {updateColorMutation.isPending ? "Saving..." : "Save Changes"}
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <div className="text-center py-12">
            <p className="text-muted-foreground">Loading colors...</p>
          </div>
        ) : colors.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-muted-foreground">No color settings found</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {colors.map((color) => {
              const currentValue = editedColors[color.id] ?? color.colorValue;
              return (
                <div key={color.id} className="space-y-2">
                  <Label htmlFor={color.id}>
                    {color.colorKey}
                    {color.description && (
                      <span className="text-xs text-muted-foreground block">
                        {color.description}
                      </span>
                    )}
                  </Label>
                  <div className="flex gap-2">
                    <Input
                      id={color.id}
                      value={currentValue}
                      onChange={(e) => handleColorChange(color.id, e.target.value)}
                      placeholder="e.g., hsl(280 60% 60%)"
                      data-testid={`input-color-${color.colorKey}`}
                    />
                    <div
                      className="w-12 h-10 rounded border"
                      style={{ backgroundColor: currentValue }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}
